True def transform(grid):
    h, w = len(grid), len(grid[0])
    best = None
    for ph in range(1, h + 1):
        for pw in range(1, w + 1):
            tile = [[None] * pw for _ in range(ph)]
            valid = True
            for r in range(h):
                for c in range(w):
                    value = grid[r][c]
                    if value == 0:
                        continue
                    rr, cc = r % ph, c % pw
                    if tile[rr][cc] is not None and tile[rr][cc] != value:
                        valid = False
                        break
                    tile[rr][cc] = value
                if not valid:
                    break
            if valid:
                score = ph * pw
                if best is None or score < best[0]:
                    best = (score, ph, pw, tile)
    _, ph, pw, tile = best
    known = [v for row in grid for v in row if v != 0]
    fallback = known[0] if known else 0
    for r in range(ph):
        for c in range(pw):
            if tile[r][c] is None:
                tile[r][c] = fallback
    return [[tile[r % ph][c % pw] for c in range(w)] for r in range(h)]
